function confirmModal(items){if(items.some(o=>o.narrationDraft)){toast('所选素材有未保存的文案，请先保存或放弃修改');return;}if(!items.length||items.some(o=>o.status!=='ready'||syncUI.locked(batch(),o))){toast('请选择已生成且无待处理问题的当前版本');return;}modal('确认 '+items.length+' 条素材可用',`<p>${isFullNarration(batch().config)?'请检查全文解说是否完整、文案与画面是否对应、配音时长和字幕是否合适，原片人声是否关闭。':'请检查剧情是否连贯、对白是否完整、字幕与 BGM 是否合适。'}系统检查通过不等于已经人工验收。</p><label class="check-confirm"><input id="confirmCheck" type="checkbox">已检查所选素材，确认当前版本可以使用</label>`,button('返回检查','close')+button('确认可用','apply-confirm','primary',`data-ids="${esc(JSON.stringify(items.map(o=>o.id)))}"`));}
document.addEventListener('change',e=>{const el=e.target;if(el.name==='bgmTrack'){const track=BGM_TRACKS.find(t=>t.id===el.value),mood=$('#bgmMood');if(track&&mood){mood.disabled=Boolean(track.mood);if(track.mood)mood.value=track.mood;}return;}const filters={dramaMarket:[libraryFilters,'market'],dramaStatus:[libraryFilters,'status'],taskDrama:[taskFilters,'drama'],taskMode:[taskFilters,'mode'],taskStatus:[taskFilters,'status']};if(filters[el.id]){filters[el.id][0][filters[el.id][1]]=el.value;render();return;}if(el.id==='dramaOutputFilter'){dramaOutputFilter=el.value;render();return;}if(el.dataset.config){const key=el.dataset.config;if(key==='titleText')return;if(key==='bgm'&&el.checked){render();openBgmPicker();return;}state.config[key]=el.type==='checkbox'?el.checked:['start','end','count','narrationSeconds','speed','narrationSpeed'].includes(key)?Number(el.value):el.value;save();if(!$('#dialog').open){if(el.type==='number'){refreshCreationPreview();return;}render();if(key==='title'&&state.config.title)$('[data-config="titleText"]')?.focus();}}if(el.dataset.plan){el.checked?planSelected.add(el.dataset.plan):planSelected.delete(el.dataset.plan);render();}if(el.dataset.output){el.checked?selected.add(el.dataset.output):selected.delete(el.dataset.output);render();}if(el.id==='pickerStart')picker.start=Number(el.value);if(el.id==='pickerEnd')picker.end=Number(el.value);if(el.id==='localFile'&&el.files[0]){if(localVideo)URL.revokeObjectURL(localVideo);localVideo=URL.createObjectURL(el.files[0]);modal('本地原片预览',`<video class="source-preview-video" controls src="${localVideo}"></video><p class="helper">仅本机播放，未上传。体验生成请切换虚构片源。</p>`,button('关闭','close')+button('使用手动片源示例','manual-source','secondary'));}});
document.addEventListener('input',e=>{if(e.target.id==='narrationEdit'||e.target.hasAttribute('data-full-narration')){const o=output();if(!o)return;const full=isFullNarration(batch().config),texts=full?$$('[data-full-narration]').map(el=>el.value):[e.target.value],original=full?o.segments.map(s=>s.text):[o.narrationText];if(texts.some((t,i)=>t!==original[i]))o.narrationDraft=texts;else delete o.narrationDraft;save();if($('#narrationDraftNotice'))$('#narrationDraftNotice').hidden=!o.narrationDraft;return;}if(e.target.id==='dramaSearch'){const pos=e.target.selectionStart;libraryFilters.query=e.target.value;render();$('#dramaSearch').focus();$('#dramaSearch').setSelectionRange(pos,pos);return;}if(e.target.dataset.config&&(e.target.type==='number'||e.target.dataset.config==='titleText')){state.config[e.target.dataset.config]=e.target.type==='number'?Number(e.target.value):e.target.value;save();refreshCreationPreview();}if(e.target.id==='collectionSearch'){const pos=e.target.selectionStart;picker.query=e.target.value;renderPicker();$('#collectionSearch').focus();$('#collectionSearch').setSelectionRange(pos,pos);}if(e.target.id==='scrubber'){stopPlayer();locate(Number(e.target.value));}});
// An interrupted local simulation releases pending work, never fabricates success.
for(const b of state.batches){for(const o of b.outputs){if(o.status==='pending')settleOutput(state,b,o,false);if(o.repairing)o.repairing=false;} }
save();render();
