 const lifecycle=new AbortController();
 const registrations=[
  {name:'inspect_mixed_cut_demo',title:'查看混剪演示状态',description:'Read the current local fictional demo configuration, planned count and example balance; does not call AI or external systems.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view,config:clone(state.config),balance:state.balance,plans:state.plan?.candidates.length||0,batches:state.batches.length,simulated:true})},
  {name:'configure_and_prepare_mixed_cut_demo',title:'配置并整理混剪演示方案',description:'Update the local fictional demo and prepare content plans. Newly analyzed example episodes consume 1 example point each; no money, AI service or real video is involved. Does not generate or sync outputs.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['highlight','narrated']},start:{type:'integer',minimum:1},end:{type:'integer',minimum:1,maximum:40},count:{type:'integer',minimum:1,maximum:20},narrationStructure:{type:'string',enum:['mixed','full']},narrationSeconds:{type:'integer',minimum:5,maximum:120},narrationSpeed:{type:'number',enum:[0.8,1,1.1,1.2,1.5]},duration:{type:'string',enum:Object.keys(RANGES)}},required:['mode','start','end','count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(busy)throw Error('分析进行中');if(localVideo)throw Error('本地文件仅预览，请先切换虚构片源');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['mode','start','end','count','narrationStructure','narrationSeconds','narrationSpeed','duration'].includes(k)))throw Error('无效配置');const c={...state.config,...input};const error=validate(c);if(error)throw Error(error);state.config=c;save();await prepare();return {view,candidates:state.plan?.candidates.length||0,balance:state.balance,simulated:true};}}
 ];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
